/** Probability and statistics, including the Mathematics 1 content assumed by STEP 2/3. */
import { tex as r, technique as t, linkedProblem as q } from './admissions-authoring.js';

export const stepStatisticsContent = {
  'probability-statistics/conditional': {
    bullets: [
      t('Combinatorial probability spaces', '组合计数与概率空间', '先指定一次结果是有序序列还是无序集合，再在等可能的基本对象上计数。', '分子与分母必须采用同一种计数口径。', r`\binom nr=\frac{n!}{r!(n-r)!}`, '区分放回与不放回、同类与可区分对象；有复杂限制时按互斥情况分类或使用补集。', r`例如从五个不同对象中无放回取两个无序对象，有 \(\binom52=10\) 种等可能选择。`, '有序与无序的计数不可混用；不同组成类型未必有相同数量的基本结果。'),
      t('Conditional partitions and Bayes reasoning', '条件划分与贝叶斯推理', '先按互斥且穷尽的原因求结果概率，再把已知结果用于更新各原因的相对权重。', '条件概率分母是已经观察到的信息的总概率。', r`P(A\mid B)=\frac{P(B\mid A)P(A)}{P(B)}\quad(P(B)>0)`, '列出原因划分，计算每条共同路径；求和得到结果概率后再归一化。', r`两袋被等概率选取，若各自红球比例为 \(\frac14\) 和 \(\frac34\)，已抽到红球时选中第二袋的概率为 \(\frac34\)。`, '先验概率不相等时不能直接比较似然；交换条件顺序通常会改变答案。'),
      t('Independence versus exclusion', '独立与互斥的区分', '独立表示得知一个事件不会改变另一个的概率，互斥表示两者不能同时发生。', '两个正概率互斥事件不独立，因为交集概率为零。', r`P(A\cap B)=P(A)P(B)\quad\text{for independence}`, '根据交集或条件概率检验独立性；需要多个事件独立时检查题目实际给出的假设。', r`公平骰子结果为一与结果为二互斥；两次独立掷骰各自为一则可同时发生。`, '两两独立不自动推出整体相互独立；不能由“两个不同事件”推断独立。'),
      t('Discrete expectation and variance', '离散期望与方差', '期望按概率加权平均，方差度量相对平均值的平方偏离，可用二阶矩计算。', '概率先归一，再计算一阶与二阶矩。', r`E(X)=\sum_x xp_x,\qquad\operatorname{Var}(X)=\sum_x x^2p_x-[E(X)]^2`, '列完整取值表并检查概率和为一；保留精确分数到最后一步。', r`公平取零或二的随机变量，期望为一，二阶矩为二，所以方差为一。`, '方差非负；二阶矩不等于方差，期望也未必是变量能实际取得的一个值。'),
    ],
    exercises: [
      q('conditional-counters', 'Conditioning on a successful draw', r`A bag contains three red and two blue counters. Two are drawn uniformly without replacement. (i) Find the probability of two red counters. (ii) Given that at least one is red, find the probability that both are red.`, '用无序组合计数，条件事件可由排除两蓝得到。', [r`There are \(\binom52=10\) equally likely pairs, of which \(\binom32=3\) are both red. Thus \(P(RR)=\frac3{10}\).`, r`Only one pair is both blue, so \(P(\text{at least one red})=\frac9{10}\). The required conditional probability is \(\frac{\frac3{10}}{\frac9{10}}=\frac13\).`]),
      q('two-coin-moments', 'A distribution from two tosses', r`Two fair coins are tossed independently and \(X\) is the number of heads. (i) Give its probability distribution. (ii) Calculate \(E(X)\), \(E(X^2)\) and \(\operatorname{Var}(X)\) directly from the distribution.`, '把四个等可能序列按正面数量分类，平方矩要先平方取值。', [r`The probabilities at \(X=0,1,2\) are respectively \(\frac14,\frac12,\frac14\).`, r`Thus \(E(X)=0+\frac12+\frac24=1\), and \(E(X^2)=0+\frac12+\frac44=\frac32\). The variance is \(\frac32-1^2=\frac12\).`]),
    ],
  },
  'probability-statistics/distributions': {
    bullets: [
      t('Binomial trials and parameters', '二项试验与参数', '固定次数、每次两类结果、独立且成功概率恒定时，成功总数服从二项分布。', '先验证次数固定、独立与同概率，再使用二项概率。', r`P(X=k)=\binom nkp^k(1-p)^{n-k},\quad E(X)=np,\quad\operatorname{Var}(X)=np(1-p)`, '把成功定义清楚，核对参数取值；至少、至多与严格不等号先转为整数事件。', r`独立投掷偏币四次、正面率三分之一，正面总数可建模为 \(\operatorname{Bin}(4,\frac13)\)。`, '无放回抽样通常不满足恒定成功概率；试验之间互相影响时也不能机械使用二项分布。'),
      t('Poisson counts and local ratios', '泊松计数与相邻概率比', '泊松分布描述适合相应随机到达模型的非负整数计数，参数同时等于平均数和方差。', '先根据观测区间调整平均计数参数。', r`P(X=k)=e^{-\lambda}\frac{\lambda^k}{k!},\quad E(X)=\operatorname{Var}(X)=\lambda`, '将单位时间率乘观察时长；比较相邻概率时阶乘比可直接消去。', r`有 \(\frac{P(X=k+1)}{P(X=k)}=\frac\lambda{k+1}\)，可用于判断众数而不计算全部概率。`, '事件成簇、速率明显变化或强相关时需质疑模型；平均率相同不保证泊松假设成立。'),
      t('Discrete uniform ranges', '离散均匀取值范围', '有限个整数等可能时，概率相同，平均数可由对称性得到，方差可通过求和计算。', '端点都包含时，连续整数的数量等于末项减首项再加一。', r`X\sim U\{1,\ldots,n\}:\quad E(X)=\frac{n+1}2,\quad\operatorname{Var}(X)=\frac{n^2-1}{12}`, '列清支持集及端点，通过平移把一般连续整数区间转成标准情形。', r`公平骰子有六个等可能取值，期望为 \(\frac72\)，方差为 \(\frac{35}{12}\)。`, '离散均匀与连续均匀的方差公式不同；对不等距支持集不能直接套连续整数公式。'),
      t('Approximations and model selection', '近似与模型选择', '二项分布在试验很多、成功率很小时可用相同均值的泊松近似，但模型前提仍需成立。', '近似需说明条件，不能把参数相同当作分布完全相同。', r`\operatorname{Bin}(n,p)\approx\operatorname{Poisson}(np)\quad\text{for large }n\text{ and small }p`, '先确定原分布，再解释近似依据；正态近似另需离散到连续的边界修正。', r`例如 \(n=1000,p=0.002\) 时，均值为二的泊松可作近似；若只有四次试验则不适合此理由。`, '没有适用于所有情境的单一硬阈值；尾部概率对近似误差可能更敏感。'),
    ],
    exercises: [
      q('binomial-four', 'An exact binomial calculation', r`Let \(X\sim\operatorname{Bin}(4,\frac13)\). (i) Find \(P(X=2)\), the mean and variance. (ii) Explain why a large-trial Poisson approximation is not justified here.`, '先精确计算，不要因均值较小就忽略试验次数只有四。', [r`The probability is \(\binom42(\frac13)^2(\frac23)^2=\frac8{27}\). The mean is \(\frac43\), and the variance is \(4\cdot\frac13\cdot\frac23=\frac89\).`, 'The trial count is only four and the success probability is not small. The usual large-n, small-p justification for a Poisson approximation does not apply.']),
      q('poisson-modes', 'Two adjacent Poisson modes', r`Let \(X\sim\operatorname{Poisson}(2)\). (i) Find \(P(X\le1)\). (ii) Derive the ratio of successive probabilities and identify every mode. (iii) State the mean and variance.`, '相邻概率比等于二除以下一个索引，等于一时会出现并列众数。', [r`We have \(P(X\le1)=e^{-2}+2e^{-2}=3e^{-2}\).`, r`The ratio is \(\frac{P(X=k+1)}{P(X=k)}=\frac2{k+1}\). It exceeds one at \(k=0\), equals one at \(k=1\), and is below one thereafter. Thus both 1 and 2 are modes.`, 'Both the mean and the variance equal 2.']),
    ],
  },
  'probability-statistics/continuous': {
    bullets: [
      t('Densities and cumulative distributions', '密度与累计分布', '连续密度的面积给概率，累计函数记录不超过某值的概率，并在可导处求导回到密度。', '密度非负且总积分为一；单点概率在连续模型下为零。', r`F(x)=P(X\le x)=\int_{-\infty}^x f(t)\,dt,\qquad f(x)=F'(x)`, '先写支持区间，求归一常数，再分段写累计函数及区间外的零和一。', r`例如 \(f(x)=2x\) 在零到一的累计函数为 \(x^2\)，左侧为零、右侧为一。`, '密度值可以大于一，不能把某点密度当成该点概率；累计函数必须单调。'),
      t('Continuous moments, medians and modes', '连续矩、中位数与众数', '密度加权积分得到期望与二阶矩，中位数把累计概率分成两半，众数取密度最大的点。', '平均数、中位数与众数一般不同。', r`E(X)=\int xf(x)\,dx,\quad E(X^2)=\int x^2f(x)\,dx,\quad F(m)=\frac12`, '先确保需要的矩存在；在支持区间积分，求中位数时检查它落在合法范围。', r`密度 \(2x\) 在零到一的平均数为 \(\frac23\)，中位数为 \(\frac1{\sqrt2}\)，二者不同。`, '密度不对称时不能把区间中点自动当平均数或中位数；反常矩可能不收敛。'),
      t('Continuous uniform intervals', '连续均匀区间', '区间内等长子区间概率相同，所以密度为区间长度的倒数，并用长度比求概率。', '连续均匀不是每个单点有同一个正概率。', r`X\sim U(a,b):\quad f(x)=\frac1{b-a},\quad E(X)=\frac{a+b}2,\quad\operatorname{Var}(X)=\frac{(b-a)^2}{12}`, '取事件区间与支持区间的交集，再用交集长度除以总长度。', r`若 \(X\sim U(-1,3)\)，则 \(P(0<X<1)=\frac14\)，平均数为一。`, '区间外密度为零；连续变量的开闭端点不改变概率，但支持区间仍须明确。'),
      t('Normal standardisation without a calculator', '正态标准化与给定概率', '将正态变量减均值再除标准差，转为标准正态，再利用对称性或题目给出的累计概率。', '标准化除的是标准差，不是方差。', r`X\sim N(\mu,\sigma^2)\quad\Longrightarrow\quad Z=\frac{X-\mu}{\sigma}\sim N(0,1)`, '把事件两端一起标准化，记录负半轴对称关系；若无概率表，保留标准累计函数表示。', r`若均值十、方差四，则横坐标十二对应标准分数一，而非二分之一。`, '标准正态尾概率不能凭记忆编造；精确数值若非标准特殊值，应由题目提供或写成累计函数。'),
      t('Normal approximations and continuity correction', '正态近似与连续性修正', '离散分布用连续正态近似时，每个整数格点对应一个宽度为一的小区间。', '先将整数事件改为半整数边界，再做正态标准化。', r`P(X\le k)\approx\Phi\!\left(\frac{k+\frac12-\mu}{\sigma}\right)`, '二项分布需成功与失败计数都不太集中在边界；泊松正态近似需均值足够大并按情境评价。', r`例如整数事件 \(X\ge10\) 应近似为连续变量大于 9.5，而非大于 10.5。`, '正态近似不对所有尾部都精确；不得把离散端点照搬为连续积分边界。'),
    ],
    exercises: [
      q('triangular-density', 'A density, its moments and median', r`A random variable has density \(f(x)=2x\) for \(0<x<1\), and zero otherwise. (i) Check normalisation and give its CDF. (ii) Find its mean and variance. (iii) Find a median.`, '依次积分密度、横坐标乘密度、横坐标平方乘密度；中位数解累计概率等于一半。', [r`The total integral is \(\int_0^1 2x\,dx=1\). Its CDF is zero for \(x\le0\), \(x^2\) for \(0<x<1\), and one for \(x\ge1\).`, r`The mean is \(\int_0^1 2x^2\,dx=\frac23\), and the second moment is \(\int_0^1 2x^3\,dx=\frac12\). The variance is \(\frac12-\frac49=\frac1{18}\).`, r`The median solves \(m^2=\frac12\) within the support, giving \(m=\frac1{\sqrt2}\).`]),
      q('normal-symmetry', 'A symmetric Normal interval', r`Let \(X\sim N(20,9)\), where the second parameter is the variance. Given \(\Phi(1)=0.8413\), (i) find \(P(17<X<23)\). (ii) Find \(P(X>23)\).`, '标准差是三，两端对应标准分数负一与一。', [r`Standardising gives \(P(17<X<23)=P(-1<Z<1)=2\Phi(1)-1=0.6826\).`, r`The upper tail is \(P(X>23)=1-\Phi(1)=0.1587\). No continuity correction is used because the stated model is already continuous.`]),
    ],
  },
  'probability-statistics/inference': {
    bullets: [
      t('Sampling and comparable data summaries', '抽样与可比较的数据摘要', '统计推断从样本谈总体，需要说明样本如何产生；数据图和摘要还需用同一种口径比较。', '随机抽样减少选择偏差，但有限样本仍有随机波动。', r`s_{\mathrm{descriptive}}^2=\frac{\sum_i(x_i-\bar x)^2}{n}=\frac{\sum_i x_i^2}{n}-\bar x^2`, '区分总体、样本与随机样本；直方图用面积表示频数，比较中心时配合离散程度。', '例如只调查自愿回复者可能过度代表感兴趣的人，即使样本人数很多也不能自动消除偏差。', '上式是所列数据的描述方差；采用样本无偏估计时分母约定不同，题目定义优先。'),
      t('Null hypotheses and tail directions', '零假设与尾部方向', '零假设给可计算的分布，备择假设决定哪一侧或哪两侧的极端结果构成证据。', '先写假设和备择方向，再看观测值。', r`H_0:p=p_0,\quad H_1:p>p_0\quad\text{or }p<p_0\text{ or }p\ne p_0`, '用情境定义参数，选统计量并确定在零假设下的分布；按事先方向计算尾部。', '例如检验硬币正面概率是否增加，备择为大于二分之一，证据来自较多正面的上尾。', '不能看结果落在哪边后再选择单尾；双尾概率的离散约定需按题目或给定规则处理。'),
      t('Binomial critical regions', '二项检验的拒绝域', '在零假设的二项分布下寻找足够极端的一组整数，使错误拒绝的概率不超过显著性水平。', '离散检验的实际显著性通常小于设定上限。', r`P_{H_0}(X\ge c)\le\alpha\quad\text{for an upper-tail critical region}`, '从极端尾部逐项累加，选最宽但仍不超水平的拒绝域；必要时展示相邻阈值为何不行。', r`若零假设下 \(X\sim\operatorname{Bin}(6,\frac12)\)，上尾只含六的概率为 \(\frac1{64}\)。`, '观测值落在非拒绝域不代表已证明零假设正确；整数阈值与连续分位数不能混用。'),
      t('P-values and evidence statements', 'p 值与证据表述', 'p 值是在零假设成立时，出现观测结果或更极端结果的概率，而不是零假设为真的概率。', '以预定显著性水平比较 p 值，再用情境语言说明证据。', r`p_{\mathrm{value}}\le\alpha\Rightarrow\text{reject }H_0\quad\text{under the specified test}`, '先确定统计量与极端方向；报告尾概率、比较关系及与备择一致的结论。', '例如 p 值为百分之三，在百分之五水平下拒绝零假设，并不说明零假设仅有百分之三的概率为真。', '统计显著不等于效应很大或模型假设正确；未拒绝也不等于接受为事实。'),
      t('Normal mean tests with known variance', '已知方差的正态均值检验', '独立正态样本的平均值仍为正态，已知方差时可用样本均值标准化检验总体均值。', '样本均值的标准差为总体标准差除以样本量平方根。', r`Z=\frac{\bar X-\mu_0}{\frac{\sigma}{\sqrt n}}\sim N(0,1)\quad\text{under }H_0`, '核对独立正态及已知方差假设，按备择选单尾或双尾，再使用题目给定的概率或临界值。', r`总体标准差为三、样本量为九时，样本均值标准差为一，并非三或三分之一。`, '未知方差不能无依据套同一个已知方差检验；相关样本也会改变均值方差。'),
    ],
    exercises: [
      q('binomial-test', 'A discrete upper-tail test', r`Six independent trials have success probability \(p\). Test \(H_0:p=\frac12\) against \(H_1:p>\frac12\) at the 5% level. (i) Find the widest upper-tail rejection region. (ii) Give its actual significance. (iii) For five observed successes, find the p-value and decision.`, '比较至少六次和至少五次成功的尾概率。', [r`Under \(H_0\), \(X\sim\operatorname{Bin}(6,\frac12)\). We have \(P(X=6)=\frac1{64}<0.05\), but \(P(X\ge5)=\frac{6+1}{64}=\frac7{64}>0.05\).`, r`Thus the rejection region is \(\{6\}\), with actual significance \(\frac1{64}=0.015625\).`, r`For five successes, the p-value is \(\frac7{64}\). The null hypothesis is not rejected: there is insufficient evidence at this level that the success probability exceeds one half.`]),
      q('normal-mean-test', 'A known-variance mean test', r`Nine independent observations come from \(N(\mu,9)\) and have sample mean 12. Test \(H_0:\mu=10\) against \(H_1:\mu>10\) at the 5% level. You may use \(\Phi(2)=0.9772\). (i) Standardise the mean. (ii) Give the p-value and conclusion.`, '先由总体标准差与样本量求均值标准差。', [r`Under \(H_0\), the sample mean has mean 10 and variance \(\frac99=1\). The observed standardised value is therefore \(z=\frac{12-10}{1}=2\).`, r`The upper-tail p-value is \(1-\Phi(2)=0.0228<0.05\). Reject \(H_0\): under the stated model, there is evidence that the population mean exceeds 10. This is not a probability statement about the truth of \(H_0\).`]),
    ],
  },
  'probability-statistics/random-variables': {
    bullets: [
      t('Algebra of expectation', '期望的代数', '期望可对线性组合逐项分配，不要求独立；非线性函数一般不能把期望直接移进去。', '线性关系可以拆期望，平方和其他非线性关系需重新计算。', r`E(aX+bY+c)=aE(X)+bE(Y)+c`, '先把所求总量写成线性组合；计数问题可设指示变量并利用其期望等于事件概率。', r`随机排列 n 个元素，固定点总数的期望为 n 个 \(\frac1n\) 相加，即一，不需各位置独立。`, '一般 \(E(X^2)\ne[E(X)]^2\)；线性期望的有效性不等于方差也能无条件相加。', 'STEP 3'),
      t('Independent variance algebra', '独立条件下的方差代数', '线性放缩使方差乘系数平方，独立随机变量相加或相减时方差均相加。', '减去独立随机变量不会把它的方差减掉。', r`\operatorname{Var}(aX\pm bY)=a^2\operatorname{Var}(X)+b^2\operatorname{Var}(Y)\quad\text{for independent }X,Y`, '先核对独立与有限方差，再平方各系数；常数项对方差没有影响。', r`若独立变量方差分别一和四，则 \(2X-Y\) 的方差为 \(4+4=8\)。`, '没有独立或其他足够条件时不能直接相加；本范围不要求协方差公式或生成函数。', 'STEP 3'),
      t('CDF transformations with multiple branches', '多分支变量变换的累计法', '从新变量事件反推原变量范围，用累计概率求新累计函数，再在可导处求密度。', '非单调变换需要保留全部原变量分支。', r`Y=X^2:\quad F_Y(y)=P(-\sqrt y\le X\le\sqrt y)\quad(y\ge0)`, '先找新支持集，再按新变量取值分段；若变换多对一，把所有逆像区间都计入。', r`当 X 在负一到一均匀分布，\(P(X^2\le y)=\sqrt y\) 对零到一的 y 成立。`, '直接使用一个反函数分支会漏概率；支持端点处密度趋于无穷也可能仍可积。', 'STEP 3'),
      t('Expectations of transformed variables', '变量函数的期望', '求变量函数的平均值时，可以直接用原密度对函数加权，不必先求新密度。', '积分的是变量函数乘原密度，而非函数的平均输入。', r`E(g(X))=\int g(x)f_X(x)\,dx`, '将新变量所需矩改写成原变量的函数，按原支持区间积分；随后用二阶矩求方差。', r`例如 \(Y=X^2\) 时 \(E(Y^2)=E(X^4)\)，可以直接在原密度下求四阶矩。`, '一般 \(E(g(X))\ne g(E(X))\)；所需积分也必须存在，不能仅凭形式计算。', 'STEP 3'),
    ],
    exercises: [
      q('independent-dice', 'A linear combination of two dice', r`Let \(X,Y\) be independent fair die scores. (i) Show \(E(X)=\frac72\) and \(\operatorname{Var}(X)=\frac{35}{12}\). (ii) Find the mean and variance of \(Z=2X-Y+3\).`, '先从六个取值直接求矩；方差中的负系数要平方。', [r`We have \(E(X)=\frac{1+2+3+4+5+6}{6}=\frac72\) and \(E(X^2)=\frac{91}{6}\). Thus \(\operatorname{Var}(X)=\frac{91}{6}-\frac{49}{4}=\frac{35}{12}\). The same holds for \(Y\).`, r`Linearity gives \(E(Z)=2\cdot\frac72-\frac72+3=\frac{13}2\). Independence gives \(\operatorname{Var}(Z)=(4+1)\frac{35}{12}=\frac{175}{12}\).`]),
      q('square-uniform', 'Squaring a uniform variable', r`Let \(X\sim U(-1,1)\) and \(Y=X^2\). (i) Find the CDF and density of \(Y\). (ii) Find its mean and variance by integrating powers of \(X\).`, '平方变换有两个原分支；期望可以直接使用原均匀密度。', [r`For \(0<y<1\), \(F_Y(y)=P(-\sqrt y\le X\le\sqrt y)=\frac{2\sqrt y}{2}=\sqrt y\). The CDF is zero at \(y\le0\) and one at \(y\ge1\).`, r`Therefore \(f_Y(y)=\frac1{2\sqrt y}\) for \(0<y<1\), and zero outside. The singular endpoint is integrable.`, r`Using \(f_X=\frac12\), \(E(Y)=E(X^2)=\frac12\int_{-1}^1x^2\,dx=\frac13\), and \(E(Y^2)=E(X^4)=\frac15\). Hence \(\operatorname{Var}(Y)=\frac15-\frac19=\frac4{45}\).`]),
    ],
  },
};
